/**
 * Review-issue model — TypeScript mirror of
 * `python/hornscribe/domain/review.py` (MASTER_PLAN §10).
 *
 * The engine converts backend-specific evidence into product-level review
 * items; the UI consumes the reason code and maps it to Japanese copy — it
 * never interprets raw backend confidence as a universal probability.
 */

/**
 * Engine-side reason codes (stable API; keep in sync with ReviewReason in
 * python/hornscribe/domain/review.py) plus the product-level reason keys the
 * copy deck defines (sidecar/review.ts REVIEW_REASON_COPY_KEYS). `(string &
 * {})` keeps autocomplete for the known codes while allowing newer engine
 * codes through verbatim — the copy layer maps them to `reviewReasons.other`.
 */
export type ReviewReason =
  | "low_model_confidence"
  | "very_short_detection"
  | "overlapping_candidates"
  | "quantization_ambiguous"
  | "possible_triplet"
  | "pitch_spelling_ambiguous"
  | "outside_preferred_horn_range"
  | "structural_measure_conflict"
  | "beat_alignment_uncertain"
  | "beat_map_uncertain"
  | "possible_grace_note"
  | "offset_ambiguous"
  | "pickup_ambiguous"
  | "meter_conflict"
  | "swing_feel"
  | "monophonic_backend"
  | "onset_uncertain"
  | "pitch_uncertain"
  | "multiple_candidates"
  | "other"
  | (string & {});

export type ReviewSeverity = "info" | "caution" | "warning";
export type ReviewIssueStatus = "open" | "accepted" | "dismissed" | "fixed";

export interface ScoreReviewIssue {
  /** `ri-<6 digits>`, allocated deterministically within one score revision. */
  readonly id: string;
  readonly scoreRevision: string;
  /** Canonical `sn-*` ids this issue points at (1+). */
  readonly canonicalNoteIds: readonly string[];
  readonly timeRange?: { readonly startSec: number; readonly endSec: number };
  readonly reason: ReviewReason;
  readonly severity: ReviewSeverity;
  /** Engine evidence payload (e.g. `{ confidence: 0.62 }`); never shown raw. */
  readonly evidence: Readonly<Record<string, unknown>>;
  readonly status: ReviewIssueStatus;
}

/** Issues still needing user attention. */
export function openIssues(issues: readonly ScoreReviewIssue[]): ScoreReviewIssue[] {
  return issues.filter((i) => i.status === "open");
}

/** All open issues touching `canonicalId` (a note can carry several). */
export function issuesForCanonical(
  issues: readonly ScoreReviewIssue[],
  canonicalId: string,
): ScoreReviewIssue[] {
  return issues.filter(
    (i) => i.status === "open" && i.canonicalNoteIds.includes(canonicalId),
  );
}

/** All issues touching `canonicalId` regardless of status — the inspector
 *  shows resolved rows too (with their status label) so a reviewed note
 *  keeps its history visible (UI-050). */
export function allIssuesForCanonical(
  issues: readonly ScoreReviewIssue[],
  canonicalId: string,
): ScoreReviewIssue[] {
  return issues.filter((i) => i.canonicalNoteIds.includes(canonicalId));
}

/** Canonical ids carrying at least one open issue — drives score markers. */
export function markedCanonicalIds(issues: readonly ScoreReviewIssue[]): Set<string> {
  const out = new Set<string>();
  for (const issue of openIssues(issues)) {
    for (const id of issue.canonicalNoteIds) out.add(id);
  }
  return out;
}

/** Optional model confidence from the evidence payload (0..1), or null.
 *  Surfaced in the inspector as evidence only — never as "probability of
 *  being wrong" (GUI_UX_PLAN §21). The engine emits `modelConfidence`
 *  (sidecar ReviewIssue dicts); `confidence` is accepted for older
 *  payloads. */
export function issueConfidence(issue: ScoreReviewIssue): number | null {
  for (const key of ["confidence", "modelConfidence"] as const) {
    const value = issue.evidence[key];
    if (typeof value === "number" && Number.isFinite(value)) return value;
  }
  return null;
}

/** Numeric evidence field, or null when absent/non-numeric. The copy
 *  layer uses this for count details (second-voice notes kept, dropped
 *  beyond two voices, merged overlaps). */
export function numEvidence(
  issue: ScoreReviewIssue,
  key: string,
): number | null {
  const value = issue.evidence[key];
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

/**
 * TypeScript mirror of the engine's ReviewIssue contract
 * (python/hornscribe/domain/review.py, MASTER_PLAN §10).
 *
 * The UI consumes product-level review items — it never interprets raw
 * backend confidence. `reason` maps onto `review.reasons.<reason>` in the
 * copy deck; unknown future reasons fall back to `review.reasons.other`
 * (UI_COPY_CONTRACT §4). The deck knows more reasons than the current
 * engine enum — that is fine (additive), the fallback covers the rest.
 */

/** Engine-side reason codes — mirrors `ReviewReason` in review.py. */
export const REVIEW_REASONS = [
  "low_model_confidence",
  "very_short_detection",
  "overlapping_candidates",
  "quantization_ambiguous",
  "pitch_spelling_ambiguous",
  "outside_preferred_horn_range",
  "structural_measure_conflict",
  "meter_conflict",
  "swing_feel",
  "monophonic_backend",
] as const;

export type ReviewReason = (typeof REVIEW_REASONS)[number];

/** Copy-deck reason keys (`review.reasons.*` in protocol/copy/ja-JP.json).
 *  A superset of the engine enum — newer decks may carry reasons the
 *  engine does not emit yet. */
export const REVIEW_REASON_COPY_KEYS = [
  "low_model_confidence",
  "very_short_detection",
  "overlapping_candidates",
  "quantization_ambiguous",
  "pitch_spelling_ambiguous",
  "outside_preferred_horn_range",
  "structural_measure_conflict",
  "beat_alignment_uncertain",
  "beat_map_uncertain",
  "possible_triplet",
  "possible_grace_note",
  "offset_ambiguous",
  "pickup_ambiguous",
  "meter_conflict",
  "swing_feel",
  "monophonic_backend",
  "onset_uncertain",
  "pitch_uncertain",
  "multiple_candidates",
  "other",
] as const;

export type ReviewReasonCopyKey = (typeof REVIEW_REASON_COPY_KEYS)[number];

/** Copy-deck key for a reason code — `other` for anything unknown. */
export function reviewReasonCopyKey(reason: string): ReviewReasonCopyKey {
  return (REVIEW_REASON_COPY_KEYS as readonly string[]).includes(reason)
    ? (reason as ReviewReasonCopyKey)
    : "other";
}

export const REVIEW_SEVERITIES = ["info", "caution", "warning"] as const;
export type ReviewSeverity = (typeof REVIEW_SEVERITIES)[number];

export const REVIEW_ISSUE_STATUSES = [
  "open",
  "accepted",
  "dismissed",
  "fixed",
] as const;
export type ReviewIssueStatus = (typeof REVIEW_ISSUE_STATUSES)[number];

/** `ReviewIssue.to_dict()` shape — camelCase per the project schema. */
export interface ReviewIssuePayload {
  id: string;
  scoreRevision: string;
  canonicalNoteIds: string[];
  timeRange: { startSec: number; endSec: number };
  reason: string;
  severity: string;
  evidence: Record<string, unknown>;
  status: string;
  [key: string]: unknown;
}

export function isReviewIssuePayload(raw: unknown): raw is ReviewIssuePayload {
  if (typeof raw !== "object" || raw === null) return false;
  const r = raw as Record<string, unknown>;
  return typeof r.id === "string" && typeof r.reason === "string";
}

/**
 * Open (unresolved) review issues carried by a completed job's
 * `result.reviewIssues` field. The contract consumed here is the handoff
 * point documented for UI-030's score-data adapter: UI-040 only needs the
 * count for the command bar / review gate, so unknown entries count as
 * issues rather than being silently dropped.
 */
export function extractReviewIssues(result: unknown): ReviewIssuePayload[] {
  if (typeof result !== "object" || result === null) return [];
  const raw = (result as Record<string, unknown>).reviewIssues;
  if (!Array.isArray(raw)) return [];
  return raw.filter(isReviewIssuePayload);
}

/** `result.reviewIssues.length`, with `result.reviewIssueCount` as a
 *  compact alternative the engine may emit instead of the full list. */
export function extractReviewIssueCount(result: unknown): number {
  const issues = extractReviewIssues(result);
  if (issues.length > 0) return issues.length;
  if (typeof result !== "object" || result === null) return 0;
  const raw = (result as Record<string, unknown>).reviewIssueCount;
  return typeof raw === "number" && raw > 0 ? Math.floor(raw) : 0;
}

